package com.projecteden.notification.controller;import java.util.List;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.projecteden.notification.dto.NotificationResponse;import com.projecteden.notification.service.NotificationService;import com.projecteden.user.domain.User;@RestController@RequestMapping("/api/notifications")public class NotificationController{private final NotificationService service;public NotificationController(NotificationService service){this.service=service;}@GetMapping public List<NotificationResponse> get(@AuthenticationPrincipal User u){return service.getNotifications(u.getId());}@PutMapping("/{id}/read")public NotificationResponse read(@AuthenticationPrincipal User u,@PathVariable Long id){return service.read(u.getId(),id);}}
